const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const siberia = ee.Geometry.Polygon([
    [[80, 50], [100, 50], [100, 60], [80, 60], [80, 50]]
  ]);

  const date1 = '2018-10-14';
  const date2 = '2018-10-29';

  // 2. Data Acquisition
  const col1 = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterBounds(siberia)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'));

  const col2 = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterBounds(siberia)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'));

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Oct 14 Images: ${size1}, Oct 29 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const img1 = col1.first();
  const img2 = col2.first();

  // 3. Processing - Calculate snow cover statistics
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = img1.select('NDSI_Snow_Cover').reduceRegion({
    reducer: reducer,
    geometry: siberia,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.select('NDSI_Snow_Cover').reduceRegion({
    reducer: reducer,
    geometry: siberia,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('NDSI_Snow_Cover_mean').getInfo();
  const count1 = stats1.get('NDSI_Snow_Cover_count').getInfo();
  const mean2 = stats2.get('NDSI_Snow_Cover_mean').getInfo();
  const count2 = stats2.get('NDSI_Snow_Cover_count').getInfo();

  console.log(`Oct 14: Mean=${mean1?.toFixed(2)}, Pixels=${count1}`);
  console.log(`Oct 29: Mean=${mean2?.toFixed(2)}, Pixels=${count2}`);

  // 4. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if snow cover values are reasonable (0-100%)
  if (mean1 < 0 || mean1 > 100 || mean2 < 0 || mean2 > 100) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (mean2 > mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
